// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;

    function setUp() public { c = new DAO(); }

    function testFuzz_property(address recipient, uint256 amount, uint256 calls) public {
        vm.assume(recipient != address(0));
        amount = bound(amount, 0, 1e30);
        calls = bound(calls, 1, 5);

        uint256 before = c.proposalCount();
        for (uint256 i = 0; i < calls; i++) {
            c.newGrantProposal(recipient, amount);
        }
        uint256 after_ = c.proposalCount();

        assertTrue(after_ == before + calls, "each newGrantProposal call must increase proposalCount by exactly 1");
    }
}
